SET NAMES utf8mb4;
CREATE TABLE schema_migrations (version VARCHAR(50) PRIMARY KEY, aplicada_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE usuarios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,rol ENUM('superadministrador','administrador') NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,ultimo_acceso DATETIME NULL,intentos_fallidos SMALLINT UNSIGNED NOT NULL DEFAULT 0,bloqueado_hasta DATETIME NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE tutores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(160) NOT NULL,identificacion VARCHAR(30) NULL,email VARCHAR(190) NULL,telefono VARCHAR(30) NULL,telefono_alt VARCHAR(30) NULL,direccion VARCHAR(255) NULL,observaciones TEXT NULL,sin_contacto_motivo VARCHAR(255) NULL,activo TINYINT(1) NOT NULL DEFAULT 1,version INT UNSIGNED NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(nombre),INDEX(telefono)) ENGINE=InnoDB;
CREATE TABLE pacientes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,tutor_id BIGINT UNSIGNED NOT NULL,nombre VARCHAR(100) NOT NULL,especie VARCHAR(60) NOT NULL,raza VARCHAR(100) NULL,sexo ENUM('macho','hembra','no_informado') NOT NULL DEFAULT 'no_informado',color VARCHAR(80) NULL,nacimiento DATE NULL,edad_estimada_meses SMALLINT UNSIGNED NULL,condicion_reproductiva VARCHAR(80) NULL,microchip VARCHAR(80) NULL,antecedentes TEXT NULL,alertas_clinicas TEXT NULL,estado ENUM('activo','inactivo','fallecido') NOT NULL DEFAULT 'activo',version INT UNSIGNED NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tutor_id) REFERENCES tutores(id),INDEX(nombre),INDEX(tutor_id),INDEX(microchip)) ENGINE=InnoDB;
CREATE TABLE atenciones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,paciente_id BIGINT UNSIGNED NOT NULL,autor_id BIGINT UNSIGNED NOT NULL,responsable_id BIGINT UNSIGNED NOT NULL,fecha_clinica DATETIME NOT NULL,motivo VARCHAR(500) NOT NULL,historia TEXT NULL,examen TEXT NULL,peso DECIMAL(8,3) NULL,diagnostico TEXT NULL,tratamiento TEXT NULL,indicaciones TEXT NULL,proximo_control DATE NULL,estado ENUM('borrador','finalizada','anulada') NOT NULL DEFAULT 'borrador',anulacion_motivo VARCHAR(500) NULL,version INT UNSIGNED NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(paciente_id) REFERENCES pacientes(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id),FOREIGN KEY(responsable_id) REFERENCES usuarios(id),INDEX(paciente_id,fecha_clinica),INDEX(estado)) ENGINE=InnoDB;
CREATE TABLE aclaraciones_atencion (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,atencion_id BIGINT UNSIGNED NOT NULL,texto TEXT NOT NULL,motivo VARCHAR(255) NULL,autor_id BIGINT UNSIGNED NOT NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(atencion_id) REFERENCES atenciones(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE archivos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,paciente_id BIGINT UNSIGNED NOT NULL,atencion_id BIGINT UNSIGNED NULL,tipo ENUM('perfil','evidencia','comprobante') NOT NULL,ruta_privada VARCHAR(255) NOT NULL,nombre_original VARCHAR(255) NOT NULL,mime VARCHAR(100) NOT NULL,tamano BIGINT UNSIGNED NOT NULL,descripcion VARCHAR(255) NULL,autor_id BIGINT UNSIGNED NOT NULL,retirado_en DATETIME NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(paciente_id) REFERENCES pacientes(id),FOREIGN KEY(atencion_id) REFERENCES atenciones(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id),INDEX(paciente_id),INDEX(atencion_id)) ENGINE=InnoDB;
CREATE TABLE servicios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(140) NOT NULL,categoria VARCHAR(100) NULL,tarifa INT UNSIGNED NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE cuentas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,atencion_id BIGINT UNSIGNED NOT NULL UNIQUE,estado ENUM('abierta','pagada','anulada') NOT NULL DEFAULT 'abierta',version INT UNSIGNED NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(atencion_id) REFERENCES atenciones(id)) ENGINE=InnoDB;
CREATE TABLE cargos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cuenta_id BIGINT UNSIGNED NOT NULL,servicio_id BIGINT UNSIGNED NULL,descripcion VARCHAR(180) NOT NULL,cantidad DECIMAL(10,2) NOT NULL DEFAULT 1,precio_unitario INT UNSIGNED NOT NULL,estado ENUM('vigente','anulado') NOT NULL DEFAULT 'vigente',anulacion_motivo VARCHAR(500) NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cuenta_id) REFERENCES cuentas(id),FOREIGN KEY(servicio_id) REFERENCES servicios(id)) ENGINE=InnoDB;
CREATE TABLE descuentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cargo_id BIGINT UNSIGNED NOT NULL,importe INT UNSIGNED NOT NULL,tipo ENUM('parcial','gratuidad') NOT NULL,motivo VARCHAR(500) NOT NULL,estado ENUM('pendiente','aprobado','rechazado') NOT NULL DEFAULT 'pendiente',solicitante_id BIGINT UNSIGNED NOT NULL,autorizante_id BIGINT UNSIGNED NULL,autorizado_en DATETIME NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cargo_id) REFERENCES cargos(id),FOREIGN KEY(solicitante_id) REFERENCES usuarios(id),FOREIGN KEY(autorizante_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE pagos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cuenta_id BIGINT UNSIGNED NOT NULL,importe INT UNSIGNED NOT NULL,medio ENUM('efectivo','transferencia','tarjeta') NOT NULL,fecha DATETIME NOT NULL,referencia VARCHAR(150) NULL,autor_id BIGINT UNSIGNED NOT NULL,operacion_id CHAR(32) NOT NULL UNIQUE,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cuenta_id) REFERENCES cuentas(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id),INDEX(fecha)) ENGINE=InnoDB;
CREATE TABLE anulaciones_pago (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pago_id BIGINT UNSIGNED NOT NULL UNIQUE,fecha DATETIME NOT NULL,motivo VARCHAR(500) NOT NULL,autor_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(pago_id) REFERENCES pagos(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE devoluciones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pago_id BIGINT UNSIGNED NOT NULL,importe INT UNSIGNED NOT NULL,medio ENUM('efectivo','transferencia','tarjeta') NOT NULL,fecha DATETIME NOT NULL,motivo VARCHAR(500) NOT NULL,autor_id BIGINT UNSIGNED NOT NULL,operacion_id CHAR(32) NOT NULL UNIQUE,FOREIGN KEY(pago_id) REFERENCES pagos(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE productos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(40) NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,categoria VARCHAR(100) NULL,unidad_base VARCHAR(30) NOT NULL,presentacion VARCHAR(80) NOT NULL,factor_conversion DECIMAL(14,4) NOT NULL DEFAULT 1,stock_minimo DECIMAL(14,4) NOT NULL DEFAULT 0,alerta_activa TINYINT(1) NOT NULL DEFAULT 1,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,producto_id BIGINT UNSIGNED NOT NULL,codigo_lote VARCHAR(80) NULL,vencimiento DATE NULL,saldo_base DECIMAL(14,4) NOT NULL DEFAULT 0,costo_unitario_base DECIMAL(14,4) NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(producto_id) REFERENCES productos(id),INDEX(producto_id,vencimiento)) ENGINE=InnoDB;
CREATE TABLE movimientos_stock (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lote_id BIGINT UNSIGNED NOT NULL,atencion_id BIGINT UNSIGNED NULL,tipo ENUM('apertura','entrada','consumo','merma','ajuste','reverso') NOT NULL,cantidad DECIMAL(14,4) NOT NULL,costo_historico DECIMAL(14,4) NULL,motivo VARCHAR(500) NULL,reverso_id BIGINT UNSIGNED NULL,autor_id BIGINT UNSIGNED NOT NULL,operacion_id CHAR(32) NOT NULL UNIQUE,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(lote_id) REFERENCES lotes(id),FOREIGN KEY(atencion_id) REFERENCES atenciones(id),FOREIGN KEY(reverso_id) REFERENCES movimientos_stock(id),FOREIGN KEY(autor_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE movimientos_financieros (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tipo ENUM('ingreso','gasto') NOT NULL,categoria VARCHAR(100) NOT NULL,descripcion VARCHAR(255) NOT NULL,importe INT UNSIGNED NOT NULL,medio ENUM('efectivo','transferencia','tarjeta') NOT NULL,fecha DATETIME NOT NULL,responsable_id BIGINT UNSIGNED NOT NULL,entrada_stock_id BIGINT UNSIGNED NULL,estado ENUM('vigente','anulado') NOT NULL DEFAULT 'vigente',operacion_id CHAR(32) NOT NULL UNIQUE,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(responsable_id) REFERENCES usuarios(id),FOREIGN KEY(entrada_stock_id) REFERENCES movimientos_stock(id),INDEX(fecha)) ENGINE=InnoDB;
CREATE TABLE cierres_caja (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,desde DATETIME NOT NULL,hasta DATETIME NOT NULL,saldo_inicial INT NOT NULL,esperado INT NOT NULL,contado INT NOT NULL,diferencia INT NOT NULL,motivo_diferencia VARCHAR(500) NULL,estado ENUM('vigente','reabierto') NOT NULL DEFAULT 'vigente',autor_id BIGINT UNSIGNED NOT NULL,operacion_id CHAR(32) NOT NULL UNIQUE,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(autor_id) REFERENCES usuarios(id),INDEX(desde,hasta)) ENGINE=InnoDB;
CREATE TABLE configuracion (clave VARCHAR(100) PRIMARY KEY,valor TEXT NULL,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE catalogos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tipo VARCHAR(60) NOT NULL,codigo VARCHAR(60) NOT NULL,etiqueta VARCHAR(120) NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,UNIQUE(tipo,codigo)) ENGINE=InnoDB;
CREATE TABLE auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NULL,accion VARCHAR(80) NOT NULL,entidad VARCHAR(80) NOT NULL,entidad_id VARCHAR(50) NULL,motivo VARCHAR(500) NULL,cambios JSON NULL,ip VARCHAR(45) NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX(creado_en),INDEX(entidad,entidad_id)) ENGINE=InnoDB;
CREATE TABLE seguimientos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,paciente_id BIGINT UNSIGNED NOT NULL,atencion_id BIGINT UNSIGNED NULL,tipo ENUM('vacuna','desparasitacion','control','examen','medicamento','procedimiento','otro') NOT NULL,titulo VARCHAR(160) NOT NULL,fecha_programada DATE NOT NULL,prioridad ENUM('normal','alta') NOT NULL DEFAULT 'normal',estado ENUM('pendiente','completado','cancelado') NOT NULL DEFAULT 'pendiente',observaciones VARCHAR(1000) NULL,contacto_resultado VARCHAR(255) NULL,contactado_en DATETIME NULL,creado_por BIGINT UNSIGNED NOT NULL,completado_por BIGINT UNSIGNED NULL,completado_en DATETIME NULL,creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(paciente_id) REFERENCES pacientes(id),FOREIGN KEY(atencion_id) REFERENCES atenciones(id),FOREIGN KEY(creado_por) REFERENCES usuarios(id),FOREIGN KEY(completado_por) REFERENCES usuarios(id),INDEX(estado,fecha_programada),INDEX(paciente_id,fecha_programada)) ENGINE=InnoDB;
INSERT INTO schema_migrations(version) VALUES ('001_inicial');
